import{at as e,it as t,n,vt as r}from"./chunks/framework.D9OOHiq-.js";var i=JSON.parse(`{"title":"物品装配系统","description":"","frontmatter":{},"headers":[],"relativePath":"modules/corelib/assembly.md","filePath":"modules/corelib/assembly.md","lastUpdated":0}`),a={name:`modules/corelib/assembly.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="物品装配系统" tabindex="-1">物品装配系统 <a class="header-anchor" href="#物品装配系统" aria-label="Permalink to “物品装配系统”">​</a></h1><p>装配系统把多个模块写进同一件物品的内容, 合并成你最终看到的名称和 Lore</p><p>简单说, 装配系统就是把各模块写进物品的状态, 统一合并成最终展示. 你的装备能一路成长, 靠的就是它</p><h2 id="为什么需要装配系统" tabindex="-1">为什么需要装配系统 <a class="header-anchor" href="#为什么需要装配系统" aria-label="Permalink to “为什么需要装配系统”">​</a></h2><p>一件 RPG 装备上, 往往同时带着好几个模块写进去的内容:</p><ul><li>EmakiItem 写入的基础名称, 基础 Lore, 套装, 技能</li><li>EmakiForge 写入的品质, 锻造材料, 额外属性</li><li>EmakiStrengthen 写入的星级, 强化加成, 失败标记</li><li>EmakiGem 写入的插槽, 宝石, 宝石等级</li><li>EmakiAttribute 写入或读取的属性 payload</li></ul><p>如果每个模块都直接改最终的 Lore, 就会互相覆盖, 出现重复, 顺序混乱, 还会留下残留. 装配系统的做法是: 各模块往自己那一层 (layer) 写结构化数据, CoreLib 再统一渲染出最终展示</p><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to “核心概念”">​</a></h2><table tabindex="0"><thead><tr><th>概念</th><th>说明</th></tr></thead><tbody><tr><td>namespace layer</td><td>每个模块在物品上占一层数据, 这一层里装着该模块写进去的所有状态</td></tr><tr><td>order</td><td>层的排序权重, 决定最终 Lore 里各模块的展示谁先谁后</td></tr><tr><td>snapshot</td><td>某一层数据的快照, 用来编解码和保存</td></tr><tr><td>contribution</td><td>这一层对最终展示的贡献, 包括 Lore 区块, 名称修饰和属性统计</td></tr><tr><td>renderer</td><td>渲染器, 负责把所有层的贡献合并成最终的 ItemMeta</td></tr></tbody></table><h2 id="namespace-layer" tabindex="-1">namespace layer <a class="header-anchor" href="#namespace-layer" aria-label="Permalink to “namespace layer”">​</a></h2><table tabindex="0"><thead><tr><th>Namespace</th><th>Order</th><th>说明</th></tr></thead><tbody><tr><td><code>forge</code></td><td><code>100</code></td><td>锻造层, 装着品质, 材料贡献和锻造配方信息</td></tr><tr><td><code>strengthen</code></td><td><code>200</code></td><td>强化层, 装着星级, 锻印, 保护状态和强化属性</td></tr><tr><td><code>gem</code></td><td><code>300</code></td><td>宝石层, 装着插槽, 宝石, 等级和宝石属性</td></tr><tr><td><code>cooking</code></td><td><code>10000</code></td><td>烹饪的展示层, 或用于特殊展示</td></tr></tbody></table><p><code>order</code> 数字越小越靠前, 你可以用它控制最终 Lore 里各模块谁先谁后</p><h2 id="装配流程" tabindex="-1">装配流程 <a class="header-anchor" href="#装配流程" aria-label="Permalink to “装配流程”">​</a></h2><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>1. 业务模块完成操作 (如强化成功, 宝石镶嵌)</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>2. 模块把真实状态写入 PDC (layer snapshot)</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>3. 模块通过 ItemOperationLedger 执行 name_actions/lore_actions</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>4. Ledger 记录操作到 PDC (emaki:item_operations), 支持后续精确回退</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>5. 返回更新后的 ItemStack</span></span></code></pre></div><p>需要撤销操作时 (如宝石提取, 强化降级), 走的是这样三步:</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>1. 模块调用 Ledger.revert (operationId) 或 Ledger.revertAll (sourceNamespace)</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>2. Reverter 根据账本记录精确撤销对应的名称/Lore 修改</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>3. 不影响其他模块的操作结果</span></span></code></pre></div><h2 id="关键服务" tabindex="-1">关键服务 <a class="header-anchor" href="#关键服务" aria-label="Permalink to “关键服务”">​</a></h2><table tabindex="0"><thead><tr><th>服务</th><th>说明</th></tr></thead><tbody><tr><td><code>EmakiItemAssemblyService</code></td><td>物品装配的入口, 接收重建请求并协调各个 layer</td></tr><tr><td><code>ItemOperationLedger</code></td><td>统一的名称/Lore 操作账本, 支持精确回退</td></tr><tr><td><code>ItemOperationExecutor</code></td><td>执行 name_actions/lore_actions, 并把变更记下来</td></tr><tr><td><code>ItemOperationReverter</code></td><td>按账本记录精确回退操作</td></tr><tr><td><code>EmakiNamespaceRegistry</code></td><td>负责 namespace 的注册和顺序管理, 记着所有已注册 layer 的 order</td></tr><tr><td><code>EmakiItemLayerCodecRegistry</code></td><td>负责 layer 数据的编码, 解码和兼容, 处理版本迁移</td></tr></tbody></table><h2 id="lore-操作账本-itemoperationledger" tabindex="-1">Lore 操作账本 (ItemOperationLedger) <a class="header-anchor" href="#lore-操作账本-itemoperationledger" aria-label="Permalink to “Lore 操作账本 (ItemOperationLedger)”">​</a></h2><p>模块每执行一次 <code>name_actions</code> 或 <code>lore_actions</code>, Ledger 都会生成一条带 <code>operationId</code> 的记录, 存进物品的 PDC (物品自带的附加数据存储) (<code>emaki:item_operations</code>)</p><p>每条记录包含:</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><code>operationId</code></td><td>这次操作的唯一标识</td></tr><tr><td><code>sourceNamespace</code></td><td>这条操作来自哪个模块 (如 <code>gem</code>, <code>strengthen</code>, <code>forge</code>)</td></tr><tr><td><code>timestamp</code></td><td>操作发生的时间</td></tr><tr><td><code>nameRecords</code></td><td>名称的修改记录 (用来回退)</td></tr><tr><td><code>loreRecords</code></td><td>Lore 的修改记录 (用来回退)</td></tr></tbody></table><p>核心 API:</p><table tabindex="0"><thead><tr><th>方法</th><th>说明</th></tr></thead><tbody><tr><td><code>apply(itemStack, operationId, sourceNamespace, nameActions, loreActions, variables)</code></td><td>执行操作, 并记进 PDC</td></tr><tr><td><code>revert(itemStack, operationId)</code></td><td>精确撤销指定的这次操作</td></tr><tr><td><code>revertAll(itemStack, sourceNamespace)</code></td><td>清空某个命名空间下的所有操作</td></tr></tbody></table><h2 id="名称修饰-name-contribution" tabindex="-1">名称修饰 (Name Contribution) <a class="header-anchor" href="#名称修饰-name-contribution" aria-label="Permalink to “名称修饰 (Name Contribution)”">​</a></h2><p>除了 Lore, layer 还可以给物品名称加修饰. 例如:</p><ul><li>强化层在名称前添加 <code>+10</code></li><li>锻造层在名称后添加品质标签 <code>[史诗]</code></li><li>宝石层不修改名称</li></ul><p>名称修饰可以指定加在名称的哪个位置:</p><table tabindex="0"><thead><tr><th>位置</th><th>说明</th></tr></thead><tbody><tr><td><code>PREFIX</code></td><td>加在名称前面</td></tr><tr><td><code>POSTFIX</code></td><td>加在名称后面</td></tr></tbody></table><p>多个 layer 的名称修饰会按 order 排序, 再依次拼起来</p><div class="note custom-block"><p class="custom-block-title custom-block-title-default">NOTE</p><p>位置枚举值是 <code>PREFIX</code> 和 <code>POSTFIX</code>, 不是 <code>SUFFIX</code></p></div><h2 id="配置者能做什么" tabindex="-1">配置者能做什么 <a class="header-anchor" href="#配置者能做什么" aria-label="Permalink to “配置者能做什么”">​</a></h2><p>你不会直接操作装配服务, 但你的配置会直接影响最终展示:</p><h3 id="调整-lore-模板" tabindex="-1">调整 Lore 模板 <a class="header-anchor" href="#调整-lore-模板" aria-label="Permalink to “调整 Lore 模板”">​</a></h3><p>每个模块的 Lore 模板就写在它自己的配置里:</p><div class="language-yaml" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># EmakiStrengthen 配置示例</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">lore</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  template</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;&lt;gray&gt;强化等级：&lt;yellow&gt;+%star%&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;&lt;gray&gt;强化加成：&lt;green&gt;+%bonus_attack% 攻击&#39;</span></span></code></pre></div><h3 id="调整属性展示格式" tabindex="-1">调整属性展示格式 <a class="header-anchor" href="#调整属性展示格式" aria-label="Permalink to “调整属性展示格式”">​</a></h3><p>属性怎么显示, 定义在 EmakiAttribute 的 <code>lore_formats/</code> 里:</p><div class="language-yaml" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># lore_formats/default_flat.yml</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">format</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;&lt;gray&gt;%display_name%：&lt;white&gt;+%value%&#39;</span></span></code></pre></div><h3 id="控制展示开关" tabindex="-1">控制展示开关 <a class="header-anchor" href="#控制展示开关" aria-label="Permalink to “控制展示开关”">​</a></h3><p>有些模块还能配置要不要显示某些状态:</p><div class="language-yaml" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">display</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  show_quality</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  show_material_info</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  show_star_level</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  show_gem_slots</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span></code></pre></div><h3 id="使用模块命令刷新装备" tabindex="-1">使用模块命令刷新装备 <a class="header-anchor" href="#使用模块命令刷新装备" aria-label="Permalink to “使用模块命令刷新装备”">​</a></h3><p>配置改完后, 已有装备的展示不会自动更新, 用模块提供的刷新命令即可:</p><ul><li>手动刷新单件装备</li><li>批量刷新在线玩家装备</li><li>玩家登录时自动刷新 (如果模块支持)</li></ul><h2 id="设计装备展示的建议" tabindex="-1">设计装备展示的建议 <a class="header-anchor" href="#设计装备展示的建议" aria-label="Permalink to “设计装备展示的建议”">​</a></h2><ul><li><strong>把&quot;真实数值&quot;放进 PDC / 属性 payload, 别只写 Lore</strong>. Lore 是给玩家看的, PDC 才是存数据的地方</li><li><strong>Lore 里只放玩家需要看到的信息</strong>. 内部调试数据不要摆进去</li><li><strong>每个模块的 Lore 区块界限要清楚</strong>. 锻造区, 强化区, 宝石区各管各的, 不要交叉</li><li><strong>别让两个模块写同一行一样的属性</strong>. 攻击力只在一个地方展示, 玩家才不会看花眼</li><li><strong>升级旧装备前, 先在测试服抽样刷新</strong>. 确认新模板不会弄坏旧数据的展示</li><li><strong>名称修饰保持简洁</strong>. <code>+10 烈焰剑 [史诗]</code> 比 <code>[+10][史诗][锻造][宝石x3] 烈焰剑</code> 好读得多</li></ul><h2 id="装配触发时机" tabindex="-1">装配触发时机 <a class="header-anchor" href="#装配触发时机" aria-label="Permalink to “装配触发时机”">​</a></h2><p>下面这些操作都会触发物品重建:</p><table tabindex="0"><thead><tr><th>操作</th><th>触发模块</th></tr></thead><tbody><tr><td>强化成功/失败</td><td>EmakiStrengthen</td></tr><tr><td>锻造完成</td><td>EmakiForge</td></tr><tr><td>宝石镶嵌/提取/升级</td><td>EmakiGem</td></tr><tr><td>物品自动更新</td><td>EmakiItem</td></tr><tr><td>手动刷新命令</td><td>各模块</td></tr><tr><td>属性同步</td><td>EmakiAttribute</td></tr></tbody></table><h2 id="lore-操作里-anchor-的匹配规则" tabindex="-1">Lore 操作里 anchor 的匹配规则 <a class="header-anchor" href="#lore-操作里-anchor-的匹配规则" aria-label="Permalink to “Lore 操作里 anchor 的匹配规则”">​</a></h2><p>用 <code>lore_actions</code> 里的 <code>insert_below</code> 或 <code>insert_above</code> 时要注意: <code>anchor</code> 留空, 和 <code>anchor</code> 没匹配到任何行, 结果并不一样:</p><table tabindex="0"><thead><tr><th>操作</th><th><code>anchor</code> 为空</th><th><code>anchor</code> 未匹配到任何行</th></tr></thead><tbody><tr><td><code>insert_below</code></td><td>插入到 Lore 末尾</td><td>插入到 Lore 末尾</td></tr><tr><td><code>insert_above</code></td><td>插入到 Lore 开头</td><td>插入到 Lore 末尾</td></tr></tbody></table><p><code>anchor</code> 用的是<strong>包含匹配</strong> (contains), 命中第一行就停; <code>insert_below</code> 插在该行之后, <code>insert_above</code> 插在该行之前</p><h2 id="namespace-id-规范化" tabindex="-1">Namespace ID 规范化 <a class="header-anchor" href="#namespace-id-规范化" aria-label="Permalink to “Namespace ID 规范化”">​</a></h2><p>注册 namespace 时, ID 会自动按下面的规则整理:</p><ul><li>去除首尾空格</li><li>转为小写</li><li>空格替换为下划线</li><li>空字符串变为 <code>unknown</code></li></ul>`,57)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};